INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a1','artikel','artikel-kas-laci-selisih','5 Penyebab Kas Laci Konter Selisih dan Cara Mengatasinya','Kas & Keuangan','["Kas Laci","BRILink"]','Selisih kas hampir selalu berasal dari kebiasaan pencatatan, bukan kecurangan. Kenali penyebabnya satu per satu.','','','center',0,'',4,0,'published','artikel/artikel-kas-laci-selisih.html','','','2026-10-26T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a2','artikel','artikel-kulakan-berdasarkan-data','Kulakan Pulsa dan Aksesori Berdasarkan Data, Bukan Firasat','Stok & Kulakan','["Stok","Analisis AI"]','Barang yang terasa laku belum tentu paling menghasilkan. Begini cara membaca data penjualan sebelum belanja stok.','','','center',1,'',4,0,'published','artikel/artikel-kulakan-berdasarkan-data.html','','','2026-10-24T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a3','artikel','artikel-batas-minimum-uang-laci','Kenapa Konter BRILink Perlu Batas Minimum Uang Laci','Kas & Keuangan','["Notifikasi","BRILink"]','Pelanggan datang untuk tarik tunai besar, tetapi uang di laci tidak cukup. Peringatan dini mencegah hal itu.','','','center',2,'',3,0,'published','artikel/artikel-batas-minimum-uang-laci.html','','','2026-10-21T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a4','artikel','artikel-absensi-gps-konter','Absensi GPS untuk Konter: Menutup Celah Kehadiran','Tim & Absensi','["Absensi","Karyawan"]','Absensi manual mudah dimanipulasi. Lokasi GPS dan kasir yang terkunci sebelum absen membuat jadwal lebih tertib.','','','center',3,'',3,0,'published','artikel/artikel-absensi-gps-konter.html','','','2026-10-18T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a5','artikel','artikel-kpi-bonus-adil','Menyusun KPI Sederhana dan Bonus yang Adil untuk Karyawan Toko','Tim & Absensi','["KPI","Gaji"]','KPI tidak harus rumit. Tiga sampai lima indikator sudah cukup untuk menilai karyawan konter.','','','center',4,'',4,0,'published','artikel/artikel-kpi-bonus-adil.html','','','2026-10-14T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('a6','artikel','artikel-kasir-offline-pwa','Jualan Tetap Jalan Saat Sinyal Mati: Cara Kerja Kasir Offline','Fitur & Panduan','["Offline","PWA"]','Sinyal di konter tidak selalu stabil. Aplikasi kasir yang offline-first membuat transaksi tetap tercatat.','','','center',5,'',3,0,'published','artikel/artikel-kasir-offline-pwa.html','','','2026-10-10T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g1','panduan','cara-mendaftar-dan-login','Cara Mendaftar dan Login ke NoctaPOS','Memulai NoctaPOS','[]','Buat akun, masuk, dan siapkan toko pertamamu dalam beberapa menit.','','','center',0,'<h2>Informasi Umum</h2><p>Akun NoctaPOS dipakai untuk masuk ke kasir dan melihat laporan toko. Satu akun bisa dipakai di perangkat berbeda.</p><h2>Membuat akun baru</h2><ol><li>Klik tombol <strong>Coba Gratis</strong> di halaman utama.</li><li>Isi nama, email, dan password.</li><li>Ikuti petunjuk di layar sampai akun aktif.</li></ol><h2>Masuk ke akun</h2><p>Klik <strong>Login</strong>, lalu masukkan email dan password yang sudah didaftarkan.</p><h2>Tips</h2><ul><li>Gunakan password yang tidak dipakai di layanan lain.</li><li>Jangan bagikan password ke karyawan, buat akun terpisah untuk mereka.</li></ul>',3,0,'published','','','','2026-11-01T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g2','panduan','menyiapkan-saldo-awal-kas-dan-bank','Menyiapkan Saldo Awal Kas dan Bank','Memulai NoctaPOS','[]','Isi saldo awal supaya kas tunai dan saldo bank terpisah dan mudah dicocokkan.','','','center',4,'<h2>Informasi Umum</h2><p>NoctaPOS memisahkan kas tunai di laci dan saldo bank. Isi keduanya di awal agar laporan akurat sejak hari pertama.</p><h2>Langkah-langkah</h2><ol><li>Hitung uang tunai yang ada di laci sekarang.</li><li>Cek saldo rekening yang dipakai untuk layanan bank.</li><li>Masukkan kedua angka sebagai saldo awal.</li></ol><h2>Tips</h2><p>Lakukan pengisian saat toko tutup supaya tidak ada transaksi yang tercampur.</p>',4,0,'published','','','','2026-11-02T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g3','panduan','cara-menambahkan-produk-baru','Cara Menambahkan Produk Baru','Transaksi & Penjualan','[]','Tambahkan produk, harga, dan stok awal agar siap dijual di kasir.','','','center',0,'<h2>Informasi Umum</h2><p>Produk yang sudah ditambahkan akan muncul di kasir dan ikut terhitung di laporan stok.</p><h2>Menambahkan produk</h2><ol><li>Buka menu <strong>Produk</strong>.</li><li>Klik tombol tambah (<strong>+</strong>).</li><li>Isi nama produk, harga beli, harga jual, dan stok awal.</li><li>Simpan.</li></ol><h2>Mengubah atau menghapus produk</h2><p>Pilih produk dari daftar, ubah datanya, lalu simpan. Produk yang sudah punya riwayat transaksi sebaiknya dinonaktifkan, bukan dihapus.</p><h2>Tips</h2><ul><li>Pakai nama yang konsisten, misalnya <em>Pulsa Tsel 10K</em>.</li><li>Isi harga beli supaya laba bisa dihitung.</li></ul>',5,1,'published','','','','2026-11-03T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g4','panduan','cara-memproses-transaksi-penjualan','Cara Memproses Transaksi Penjualan','Transaksi & Penjualan','[]','Catat penjualan dari memilih produk sampai pembayaran selesai.','','','center',2,'<h2>Informasi Umum</h2><p>Setiap penjualan tercatat otomatis ke kas dan stok. Transaksi tetap bisa dicatat saat sinyal mati.</p><h2>Langkah-langkah</h2><ol><li>Buka halaman <strong>Kasir</strong>.</li><li>Pilih produk yang dibeli pelanggan.</li><li>Periksa jumlah dan total belanja.</li><li>Pilih metode bayar, lalu konfirmasi.</li></ol><h2>Jika salah input</h2><p>Segera koreksi sebelum tutup kasir supaya selisih kas tidak muncul di laporan.</p>',6,1,'published','','','','2026-11-04T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g5','panduan','mencatat-tarik-tunai-dan-setor-tunai','Mencatat Tarik Tunai dan Setor Tunai BRILink','Transaksi & Penjualan','[]','Catat transaksi agen supaya kas tunai dan saldo bank bergerak dengan benar.','','','center',1,'<h2>Informasi Umum</h2><p>Tarik tunai menambah uang di bank dan mengurangi uang di laci, sedangkan setor tunai sebaliknya. NoctaPOS mencatat keduanya terpisah.</p><h2>Langkah-langkah</h2><ol><li>Pilih jenis transaksi: tarik tunai atau setor tunai.</li><li>Masukkan nominal dan biaya admin.</li><li>Konfirmasi transaksi.</li></ol><h2>Tips</h2><p>Catat tepat saat transaksi berlangsung, jangan menumpuk di akhir hari.</p>',5,0,'published','','','','2026-11-05T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g6','panduan','cara-membaca-laporan-penjualan','Cara Membaca Laporan Penjualan','Laporan & Analitik','[]','Pahami angka omzet, laba, dan produk terlaris di laporan.','','','center',3,'<h2>Informasi Umum</h2><p>Laporan penjualan merangkum transaksi per hari atau per periode, sehingga kamu tahu mana yang laku dan mana yang menghasilkan.</p><h2>Yang perlu dilihat</h2><ul><li><strong>Omzet</strong>: total uang masuk dari penjualan.</li><li><strong>Laba</strong>: omzet dikurangi harga beli.</li><li><strong>Produk terlaris</strong>: acuan untuk kulakan berikutnya.</li></ul><h2>Membandingkan periode</h2><p>Bandingkan minggu ini dengan minggu lalu untuk melihat tren. Barang yang terasa laku belum tentu paling menguntungkan.</p>',7,1,'published','','','','2026-11-06T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g7','panduan','mencocokkan-kas-laci-saat-tutup-kasir','Mencocokkan Kas Laci Saat Tutup Kasir','Laporan & Analitik','[]','Hitung uang fisik dan bandingkan dengan catatan sistem untuk menemukan selisih.','','','center',4,'<h2>Informasi Umum</h2><p>Di akhir shift, hitung uang fisik di laci lalu masukkan ke NoctaPOS. Sistem langsung menunjukkan selisihnya.</p><h2>Langkah-langkah</h2><ol><li>Hitung uang fisik di laci.</li><li>Masukkan nominalnya saat tutup kasir.</li><li>Periksa selisih yang muncul.</li></ol><h2>Jika ada selisih</h2><p>Cek transaksi hari itu, terutama tarik tunai dan setor tunai yang belum dicatat.</p>',4,0,'published','','','','2026-11-07T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g8','panduan','mengatur-batas-minimum-uang-laci','Mengatur Batas Minimum Uang Laci','Pengaturan & Personalisasi','[]','Dapatkan peringatan saat uang di laci hampir habis.','','','center',2,'<h2>Informasi Umum</h2><p>Batas minimum membuat kamu diperingatkan sebelum uang laci tidak cukup untuk tarik tunai pelanggan.</p><h2>Langkah-langkah</h2><ol><li>Buka menu <strong>Pengaturan</strong>.</li><li>Cari pengaturan batas minimum kas.</li><li>Isi nominal sesuai kebutuhan toko, lalu simpan.</li></ol>',3,0,'published','','','','2026-11-08T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g9','panduan','mengaktifkan-laporan-harian-ke-telegram','Mengaktifkan Laporan Harian ke Telegram','Pengaturan & Personalisasi','[]','Terima ringkasan toko langsung di Telegram.','','','center',5,'<h2>Informasi Umum</h2><p>Laporan ke Telegram membuat pemilik tetap tahu kondisi toko tanpa harus membuka aplikasi.</p><h2>Langkah-langkah</h2><ol><li>Buka menu <strong>Pengaturan</strong>, lalu bagian Telegram.</li><li>Ikuti petunjuk untuk menghubungkan akun Telegram.</li><li>Pilih laporan atau notifikasi yang ingin diterima.</li></ol>',4,0,'published','','','','2026-11-09T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g10','panduan','transaksi-offline-belum-tersinkron','Transaksi Offline Belum Tersinkron, Apa yang Harus Dilakukan?','Bantuan & Pemecahan Masalah','[]','Langkah cek saat transaksi yang dicatat tanpa sinyal belum muncul di laporan.','','','center',1,'<h2>Informasi Umum</h2><p>Saat sinyal mati, transaksi disimpan di perangkat dan dikirim otomatis begitu koneksi kembali.</p><h2>Yang bisa dicoba</h2><ol><li>Pastikan perangkat sudah terhubung ke internet.</li><li>Biarkan aplikasi terbuka beberapa saat agar sinkronisasi berjalan.</li><li>Jangan menghapus data browser atau aplikasi sebelum sinkron selesai.</li></ol><h2>Masih bermasalah?</h2><p>Hubungi tim kami lewat halaman Kontak dan sertakan waktu transaksi yang belum muncul.</p>',4,0,'published','','','','2026-11-10T08:00:00.000Z','');
INSERT OR IGNORE INTO content (id,type,slug,title,category,tags,excerpt,cover,cover_alt,cover_pos,grad,html,minutes,popular,status,legacy_url,meta_title,meta_desc,created_at,updated_at) VALUES ('g11','panduan','absensi-gps-karyawan','Absensi GPS Karyawan','Fitur Lainnya','[]','Pakai lokasi GPS agar kehadiran karyawan tercatat lebih tertib.','','','center',3,'<h2>Informasi Umum</h2><p>Absensi GPS memastikan karyawan absen dari lokasi toko, dan kasir terkunci sebelum absen dilakukan.</p><h2>Langkah-langkah</h2><ol><li>Aktifkan fitur absensi di pengaturan.</li><li>Pastikan lokasi toko sudah diatur.</li><li>Minta karyawan mengizinkan akses lokasi di perangkatnya.</li></ol>',4,0,'published','','','','2026-11-11T08:00:00.000Z','');
